effect.shader:
float hash21(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }

float distReta(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
    return length(pa - ba * h);
}

void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    vec2 A = pointA, B = pointB;
    vec2 p = acScreenNorm;

    // t ao longo da linha
    vec2 ba = B - A;
    float len2 = max(dot(ba, ba), 1e-6);
    float t = clamp(dot(p - A, ba) / len2, 0.0, 1.0);

    // o arco é a reta mais um deslocamento perpendicular barulhento
    vec2 n = vec2(-ba.y, ba.x) / sqrt(len2);
    float semente = floor(acTime * speed);
    float ruido = 0.0;
    float amp = 1.0;
    for (int i = 0; i < 4; i++) {
        float f = pow(2.0, float(i)) * 6.0;
        ruido += (hash21(vec2(floor(t * f), semente + float(i))) - 0.5) * amp;
        amp *= 0.5;
    }
    ruido *= jitter * (1.0 - abs(t - 0.5) * 2.0);
    vec2 aoLongo = mix(A, B, t) + n * ruido;
    float d = length(p - aoLongo);

    float raio = smoothstep(width * 3.0, width, d);
    float glow = smoothstep(width * 15.0, width * 3.0, d) * 0.5;
    vec3 cor = orig.rgb + tint.rgb * tint.a * (raio + glow);
    fragColor = vec4(cor, max(orig.a, (raio + glow) * tint.a));
}
